mapper.select:
/* saleson.shop.notice.SysNoticeSellerMapper.getNoticeCount */
SELECT COUNT(*)
FROM OP_SYS_NOTICE_SELLER N


		AND SUB_CATEGORY = #{subCategory}



			AND SUBJECT LIKE CONCAT('%', #{query}, '%')


			AND CONTENT LIKE CONCAT('%', #{query}, '%')



    	AND DATE_FORMAT(frst_crt_dt, '%Y%m%d') BETWEEN #{startDt} AND #{endDt}


		AND N.LOCGOV_CODE = #{locgovCode}





			AND BOARD_CODE = #{boardCode}


			AND BOARD_CODE IS NULL



	AND USE_YN = 'Y'

/* saleson.shop.notice.SysNoticeSellerMapper.getNoticeList */
SELECT N.notice_id, N.subject, N.content, N.hits, N.board_code, N.sub_category, N.notice_flag, N.frst_crt_id, N.frst_crt_dt, N.last_mdfcn_id, N.last_mdfcn_dt, CASE WHEN ADDDATE(N.frst_crt_dt, INTERVAL 3 DAY) >= THEN 'Y' ELSE 'N' END AS new_flag, N.display_flag, N.use_yn, N.locgov_code, (SELECT count(*) from OP_SYS_NOTICE_SELLER_FILE WHERE use_yn = 'Y' and notice_id = N.notice_id) as attached_file_cnt FROM OP_SYS_NOTICE_SELLER N
AND SUB_CATEGORY = #{subCategory}
AND DATE_FORMAT(frst_crt_dt, '%Y%m%d') BETWEEN #{startDt} AND #{endDt}
AND SUBJECT LIKE CONCAT('%', #{query}, '%')
AND CONTENT LIKE CONCAT('%', #{query}, '%')
AND N.LOCGOV_CODE = #{locgovCode}
AND BOARD_CODE = #{boardCode}
AND BOARD_CODE IS NULL
AND USE_YN = 'Y'
ORDER BY notice_flag DESC, frst_crt_dt DESC

mapper.insert:
/* saleson.shop.notice.SysNoticeSellerMapper.insertNotice */
INSERT INTO
	OP_SYS_NOTICE_SELLER
	(
		SUBJECT
		, CONTENT
		, HITS
		, BOARD_CODE
		, SUB_CATEGORY
		, NOTICE_FLAG
		, DISPLAY_FLAG
		, LOCGOV_CODE
		, USE_YN
		, FRST_CRT_ID
		, FRST_CRT_DT
	)
VALUES
	(
	 	#{subject}
	 	, #{content}
	 	, 0
	 	, #{boardCode}
	 	, #{subCategory}
	 	, #{noticeFlag}
	 	, #{displayFlag}
	 	, #{locgovCode}
	 	, 'Y'
	 	, #{frstCrtId}
	 	, NOW()
	 )

INSERT INTO
	OP_SYS_NOTICE_SELLER_FILE
	(
		NOTICE_ID
		, ORGNL_ATCH_FILE_NM
		, ATCH_FILE_NM
		, ATCH_FILE_EXTN_NM
		, ATCH_FILE_SZ
		, ATCH_FILE_SEQ
		, ATCH_FILE_PATH_NM
		, FRST_CRT_ID
		, FRST_CRT_DT
	)
VALUES
	(
		#{noticeId}
		, #{orgnlAtchFileNm}
		, #{atchFileNm}
		, #{atchFileExtnNm}
		, #{atchFileSz}
		, (SELECT IFNULL(MAX(ATCH_FILE_SEQ)+1, 1) FROM OP_SYS_NOTICE_SELLER_FILE WHERE NOTICE_ID = #{noticeId})
		, #{atchFilePathNm}
		, #{frstCrtId}
		, NOW()
	)

mapper.update:
/**cmnty-mapper.deleteNoticeFileByFileId */
UPDATE
	OP_SYS_NOTICE_SELLER_FILE
SET
	USE_YN = 'N'
	, LAST_MDFCN_ID = #{lastMdfcnId}
	, LAST_MDFCN_DT = NOW()
WHERE
	FILE_ID = #{fileId}

/**cmnty-mapper.deleteNoticeFileByNoticeId */
UPDATE
	OP_SYS_NOTICE_SELLER_FILE
SET
	USE_YN = 'N'
	, LAST_MDFCN_ID = #{lastMdfcnId}
	, LAST_MDFCN_DT = NOW()
WHERE
	NOTICE_ID = #{noticeId}

/* saleson.shop.notice.SysNoticeSellerMapper.updateNotice */
UPDATE
	OP_SYS_NOTICE_SELLER
SET
	SUBJECT = #{subject}
	, CONTENT = #{content}
	, NOTICE_FLAG = #{noticeFlag}
	, DISPLAY_FLAG = #{displayFlag}
	, LAST_MDFCN_ID = #{lastMdfcnId}
	, LAST_MDFCN_DT = NOW()
WHERE NOTICE_ID = #{noticeId}

/* saleson.shop.notice.SysNoticeSellerMapper.addHitCount */
UPDATE OP_SYS_NOTICE_SELLER
SET HITS = HITS + 1
WHERE NOTICE_ID = #{noticeId}

mapper.delete:
/* saleson.shop.notice.SysNoticeSellerMapper.deleteNotice */
UPDATE
	OP_SYS_NOTICE_SELLER
SET USE_YN = 'N'
	, LAST_MDFCN_ID = #{lastMdfcnId}
	, LAST_MDFCN_DT = NOW()
WHERE NOTICE_ID = #{noticeId}

